 bank:'<path d="m3 10 9-7 9 7M4 10h16M6 10v9M10 10v9M14 10v9M18 10v9M3 21h18"/>',
 cash:'<rect x="2" y="6" width="20" height="12" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M6 9h.01M18 15h.01"/>',
 wallet:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 9h18m-5 6h2"/>',
